def compute(vars):
    cost = vars["v1"]
    shares = vars["v2"]

    if shares == 0:
        return None

    price_per_share = cost / shares
    return {
        "value": price_per_share,
        "trace": {
            "aggregate_cost_million": cost,
            "shares_repurchased_million": shares,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "USD/share"
            }
        }
    }

def compute(vars):
